orders = [
    ('Ташкент', 120), ('Самарканд', 80), ('Ташкент', 340),
    ('Бухара', 60), ('Самарканд', 150), ('Ташкент', 90),
]

by_city = {}
for city, amount in orders:
    by_city[city] = by_city.get(city, 0) + amount

total = sum(by_city.values())
for city, amount in sorted(by_city.items(), key=lambda x: -x[1]):
    share = round(amount / total * 100, 1)
    print(f'{city}: {amount} ({share}%)')

